import React, { useState, useEffect } from 'react';

const ImageViewer = ({ content }) => {
  const [isOpen, setIsOpen] = useState(true);
  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);

  // Improved image array generation
  const images = content.carousel && content.images 
    ? content.images 
    : [content.image].filter(Boolean);

  // Prevent unnecessary re-renders and add keyboard navigation
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (!isOpen) return;

      switch (event.key) {
        case 'ArrowRight':
          nextSlide();
          break;
        case 'ArrowLeft':
          prevSlide();
          break;
        case 'Escape':
          closeModal();
          break;
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, currentSlideIndex]);

  const showSlide = (index) => {
    if (images.length === 0) return;

    const adjustedIndex = 
      index >= images.length ? 0 : 
      index < 0 ? images.length - 1 : 
      index;

    setCurrentSlideIndex(adjustedIndex);
  };

  const nextSlide = () => {
    showSlide(currentSlideIndex + 1);
  };

  const prevSlide = () => {
    showSlide(currentSlideIndex - 1);
  };

  const closeModal = () => {
    setIsOpen(false);
  };

  // Early return if no images or modal is closed
  if (!isOpen || images.length === 0) return null;

  return (
    <div 
      id="myModal" 
      className="modal"
      style={{
        display: 'block', 
        position: 'fixed', 
        zIndex: 1000, 
        left: 0, 
        top: 0, 
        width: '100%', 
        height: '100%', 
        overflow: 'auto', 
        backgroundColor: 'rgba(0,0,0,0.9)'
      }}
    >
      <div className="modal-content" style={{
        margin: 'auto', 
        display: 'block', 
        width: '80%', 
        maxWidth: '700px'
      }}>
        {content.carousel && images.length > 1 ? (
          <div className="carousel-container" style={{position: 'relative'}}>
            <img 
              src={images[currentSlideIndex]} 
              alt={`Slide ${currentSlideIndex + 1}`} 
              style={{
                maxWidth: '100%', 
                maxHeight: '80vh', 
                display: 'block', 
                margin: 'auto'
              }}
            />
            {images.length > 1 && (
              <>
                <button 
                  className="prev" 
                  onClick={prevSlide} 
                  style={{
                    position: 'absolute', 
                    left: '10px', 
                    top: '50%', 
                    transform: 'translateY(-50%)'
                  }}
                >
                  &#10094;
                </button>
                <button 
                  className="next" 
                  onClick={nextSlide} 
                  style={{
                    position: 'absolute', 
                    right: '10px', 
                    top: '50%', 
                    transform: 'translateY(-50%)'
                  }}
                >
                  &#10095;
                </button>
              </>
            )}
          </div>
        ) : (
          <img 
            id="modalImg" 
            src={images[0]} 
            alt="Selected" 
            style={{
              maxWidth: '100%', 
              maxHeight: '80vh', 
              display: 'block', 
              margin: 'auto'
            }}
          />
        )}

        {content.text && (
          <div 
            id="caption" 
            style={{
              color: '#fff', 
              padding: '10px', 
              textAlign: 'center'
            }}
            dangerouslySetInnerHTML={{__html: content.text}}
          />
        )}
        <span 
          className="close" 
          onClick={closeModal}
          style={{
            color: '#f1f1f1', 
            fontSize: '40px', 
            fontWeight: 'bold', 
            position: 'absolute', 
            top: '15px', 
            right: '35px', 
            cursor: 'pointer'
          }}
        >
          &times;
        </span>
      </div>
    </div>
  );
};

export default ImageViewer;
